const domain = 'jypragroup.com.au';
const kw = $('Load Keywords').item.json;
const results = Array.isArray($json.results) ? $json.results : [];
let position = null, foundUrl = null;
for (let i = 0; i < results.length; i++) {
  const u = String(results[i].url || '').toLowerCase();
  if (u.includes(domain)) { position = i + 1; foundUrl = results[i].url; break; }
}
const page = position === null ? null : Math.ceil(position / 10);
const onTarget = position !== null && page <= 2;
const isPriority = ['Quick Win', 'Commercial'].includes(kw.group);
const needs_brief = isPriority && (position === null || position > 20);
const brief_prompt = [
  'You are an Australian SEO content strategist. Write a concise, practical on-page SEO content brief.',
  'Use Australian English. Output plain text with short headed sections. No preamble.',
  '',
  'TARGET KEYWORD: ' + kw.keyword,
  'SEARCH INTENT: ' + kw.intent,
  'MONTHLY SEARCH VOLUME: ' + kw.volume,
  'KEYWORD DIFFICULTY (0-100): ' + kw.difficulty,
  'TARGET PAGE ON jypragroup.com.au: ' + kw.target_page,
  'OUR CURRENT POSITION: ' + (position === null ? 'not found in results' : String(position)),
  'TOP-RANKING COMPETITOR: ' + kw.top_company + ' at position ' + kw.top_position,
  '',
  'Produce these sections:',
  '1) META: recommended H1, meta title (<=60 chars), meta description (<=155 chars).',
  '2) OUTLINE: 5-8 H2/H3 headings that fully satisfy the search intent.',
  '3) ENTITIES: 8-10 semantically related terms to include.',
  '4) LINKS: 3 internal-link ideas + 1 type of authoritative external reference.',
  '5) INTRO: a draft intro paragraph (<=90 words) using the keyword naturally once.'
].join('\n');
return { json: {
  keyword: kw.keyword, group: kw.group, volume: kw.volume, difficulty: kw.difficulty,
  intent: kw.intent, target_page: kw.target_page, top_company: kw.top_company,
  top_position: kw.top_position, checked_at: new Date().toISOString(), domain,
  position, page, found_url: foundUrl, on_page_1_or_2: onTarget, needs_brief, brief_prompt
} };

const items = $input.all().map(i => i.json);
const total = items.length;
const ranking = items.filter(i => i.position !== null);
const onP12 = items.filter(i => i.on_page_1_or_2);
const notRanking = items.filter(i => i.position === null);
const briefs = items.filter(i => i.needs_brief);
const rows = items
  .slice()
  .sort((a, b) => (a.position == null ? 999 : a.position) - (b.position == null ? 999 : b.position))
  .map(i => '<tr><td>' + i.keyword + '</td><td>' + i.group + '</td><td>' +
    (i.position == null ? '&mdash;' : i.position) + '</td><td>' +
    (i.on_page_1_or_2 ? 'yes' : '') + '</td><td>' + i.top_company + ' (' + i.top_position + ')</td></tr>')
  .join('');
const html = '<h2>Jypra SEO rank report &mdash; ' + new Date().toLocaleDateString('en-AU') + '</h2>' +
  '<p>Domain tracked: <b>jypragroup.com.au</b></p>' +
  '<ul>' +
  '<li>Keywords tracked: ' + total + '</li>' +
  '<li>Ranking somewhere in results: ' + ranking.length + '</li>' +
  '<li>On page 1 or 2 (the goal): <b>' + onP12.length + '</b></li>' +
  '<li>Not found in results yet: ' + notRanking.length + '</li>' +
  '<li>Content briefs generated this run: ' + briefs.length + '</li>' +
  '</ul>' +
  '<table border="1" cellpadding="5" cellspacing="0" style="border-collapse:collapse;font-family:Calibri,Arial,sans-serif;font-size:13px">' +
  '<tr style="background:#2E5B8F;color:#fff"><th>Keyword</th><th>Group</th><th>Our position</th><th>Pg 1/2</th><th>Top competitor</th></tr>' +
  rows + '</table>';
return { json: {
  generated_at: new Date().toISOString(), total, ranking: ranking.length,
  on_page_1_or_2: onP12.length, not_ranking: notRanking.length, briefs: briefs.length,
  email_html: html
} };

const src = $('Parse Rank').item.json;
let out = $json.output;
if (Array.isArray(out)) out = out.join('');
return { json: {
  keyword: src.keyword, group: src.group, target_page: src.target_page,
  intent: src.intent, our_position: src.position, competitor: src.top_company,
  competitor_position: src.top_position, generated_at: new Date().toISOString(),
  content_brief: out || ''
} };
